Object.assign(SNIP,{"h10tach": "vector<string> tachTu(const string& s) {\n    vector<string> tu;\n    string w = \"\";\n    for (char c : s) {\n        if (c == ' ') {\n            if (w != \"\") tu.push_back(w);\n            w = \"\";\n        } else {\n            w += c;\n        }\n    }\n    if (w != \"\") tu.push_back(w);   // từ cuối cùng\n    return tu;\n}"});PRESET_NOTES["l10"]={"Ví dụ: Đếm chữ cái, chữ số, ký tự khác": "getline đọc cả dòng, kể cả dấu cách. Dấu cách và dấu ! được tính là ký tự khác.", "Ví dụ: Chữ cái xuất hiện nhiều nhất": "tolower đưa chữ hoa về thường rồi c - 'a' cho chỉ số 0..25. Dấu > (không phải >=) giữ chữ nhỏ nhất khi có nhiều chữ cùng số lần.", "Ví dụ: Tách từ và chuẩn hóa": "Kết quả “Hoc Sinh Gioi”: bỏ dấu cách thừa, mỗi từ viết hoa chữ đầu. w += tolower(c) thêm ký tự đã đổi về chữ thường."};EX_HINTS["l10"]=[["Đọc bằng getline để giữ dấu cách.", "Dấu cách cũng là “ký tự còn lại”."], ["cnt[tolower(c) - 'a']++ với mỗi chữ cái.", "So sánh bằng > để giữ chữ nhỏ nhất khi bằng nhau.", "In chữ: (char)('a' + best)."], ["Tách từ như mục Tách từ: bỏ qua mọi dấu cách thừa.", "w += tolower(c) để mọi chữ thành chữ thường, sau đó đổi chữ đầu bằng toupper.", "In dấu cách giữa các từ, không in ở cuối."]];
